namespace FramePilot.Monitoring {
 public sealed class ScanState {public string state {get;set;}public string message {get;set;}public int count {get;set;}public string root {get;set;}}
 public sealed class ScanEntry {public int id {get;set;}public string name {get;set;}public long size_bytes {get;set;}public bool is_directory {get;set;}}
 public sealed class ScanChildren {public ScanEntry[] rows {get;set;}public bool has_more {get;set;}}
 public interface IStorageService:IDisposable {Task<ScanState> StartAsync(string root,CancellationToken token);Task<ScanState> StatusAsync(CancellationToken token);Task CancelAsync();Task StopAsync();Task<ScanChildren> ChildrenAsync(int parent,int offset,CancellationToken token);}
 public sealed class StorageService:IStorageService {
  readonly PythonMonitorService worker=new PythonMonitorService();
  public async Task<ScanState> StartAsync(string root,CancellationToken token){await worker.StartAsync("",token).ConfigureAwait(false);return await worker.StorageRequest<ScanState>("scan_start",new Dictionary<string,object>{{"root",root}},token).ConfigureAwait(false);}
  public Task<ScanState> StatusAsync(CancellationToken token){return worker.StorageRequest<ScanState>("scan_status",null,token);}
  public async Task CancelAsync(){try{await worker.StorageRequest<ScanState>("scan_cancel",null,CancellationToken.None).ConfigureAwait(false);}catch{} }
  public Task<ScanChildren> ChildrenAsync(int parent,int offset,CancellationToken token){return worker.StorageRequest<ScanChildren>("scan_children",new Dictionary<string,object>{{"parent",parent},{"offset",offset}},token);}
  public Task StopAsync(){return worker.StopAsync();}
  public void Dispose(){worker.Dispose();}
 }
}
