   top.Children.Add(new TextBlock{Text="Scan a folder or drive with eDirStat. Accessible file sizes are estimates; protected folders may be skipped. No administrator request is made.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,14)});
   top.Children.Add(new TextBlock{Text="SCAN DRIVE OR FOLDER",FontSize=11,Foreground=new SolidColorBrush(Color.FromRgb(163,151,137)),Margin=new Thickness(1,0,0,5)});var driveRow=new DockPanel{LastChildFill=true,Margin=new Thickness(0,0,0,10)};root=new ComboBox{MinHeight=34,VerticalContentAlignment=VerticalAlignment.Center,ToolTip="Select an available drive to scan"};var refreshDrives=Action("Refresh drives",LoadDrives);refreshDrives.Margin=new Thickness(8,0,0,0);refreshDrives.Padding=new Thickness(11,6,11,6);DockPanel.SetDock(refreshDrives,Dock.Right);driveRow.Children.Add(refreshDrives);driveRow.Children.Add(root);top.Children.Add(driveRow);LoadDrives();
   var actions=new WrapPanel();actions.Children.Add(Action("Choose folder",delegate{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="Choose a folder to inspect",ShowNewFolderButton=false}){d.SelectedPath=SelectedRoot();if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)SelectFolder(d.SelectedPath);}}));
