   tree=new TreeView{Background=new SolidColorBrush(Color.FromRgb(26,22,19)),Foreground=new SolidColorBrush(Color.FromRgb(243,236,228)),BorderThickness=new Thickness(0),ItemContainerStyle=TreeItemStyle()};tree.PreviewMouseRightButtonDown+=SelectRightClickedItem;ScrollViewer.SetHorizontalScrollBarVisibility(tree,ScrollBarVisibility.Auto);VirtualizingStackPanel.SetIsVirtualizing(tree,true);Grid.SetRow(tree,1);Children.Add(tree);Loaded+=delegate{ownerWindow=Window.GetWindow(this);if(ownerWindow!=null)ownerWindow.PreviewMouseDown+=DismissContextPopup;};Unloaded+=delegate{if(ownerWindow!=null)ownerWindow.PreviewMouseDown-=DismissContextPopup;ownerWindow=null;};
