  Button Action(string text,Action action){var b=new Button{Content=text};b.Click+=delegate{try{action();}catch(Exception e){status.Text=e.Message;}};return b;}
  StorageNode Selected(){var item=tree.SelectedItem as TreeViewItem;var n=item==null?null:item.Tag as StorageNode;if(n==null)throw new Exception("Select a file or folder first.");return n;}
  async Task Scan(){
   if(busy)return;busy=true;scan.IsEnabled=false;cancel.IsEnabled=true;tree.Items.Clear();if(service!=null){await service.StopAsync();service.Dispose();}service=new StorageService();cancellation=new CancellationTokenSource();
   try{
    string selectedRoot=SelectedRoot();if(string.IsNullOrWhiteSpace(selectedRoot))throw new InvalidOperationException("No available drive is selected. Refresh the drive list or choose a folder.");var state=await service.StartAsync(selectedRoot,cancellation.Token);scannedRoot=Path.GetFullPath(state.root);
    while(state.state=="scanning"||state.state=="indexing"){status.Text=state.message;await Task.Delay(400,cancellation.Token);state=await service.StatusAsync(cancellation.Token);}
    status.Text=state.message;if(state.state=="ready"){var node=Node(scannedRoot,new StorageNode{Path=scannedRoot,Id=0,Directory=true});tree.Items.Add(node);node.IsExpanded=true;}
   }catch(OperationCanceledException){}catch(Exception e){status.Text="Storage scan unavailable: "+e.GetBaseException().Message;}
   finally{busy=false;if(!disposed){scan.IsEnabled=true;cancel.IsEnabled=false;}}
  }
  string SelectedRoot(){var selected=root.SelectedItem as DriveOption;return selected==null?null:selected.Path;}
  void SelectFolder(string path){string full=Path.GetFullPath(path);var option=root.Items.Cast<object>().OfType<DriveOption>().FirstOrDefault(x=>string.Equals(x.Path,full,StringComparison.OrdinalIgnoreCase));if(option==null){option=new DriveOption{Path=full,Label="Folder: "+full};root.Items.Add(option);}root.SelectedItem=option;}
  void LoadDrives(){string previous=SelectedRoot();root.Items.Clear();var available=new List<DriveOption>();foreach(DriveInfo drive in DriveInfo.GetDrives())try{if(!drive.IsReady)continue;string label=drive.Name;if(!string.IsNullOrWhiteSpace(drive.VolumeLabel))label+="  "+drive.VolumeLabel;label+="  ·  "+FormatSize(drive.AvailableFreeSpace)+" free";available.Add(new DriveOption{Path=drive.RootDirectory.FullName,Label=label});}catch{}foreach(var drive in available.OrderBy(x=>x.Path,StringComparer.OrdinalIgnoreCase))root.Items.Add(drive);var home=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);var preferred=available.FirstOrDefault(x=>home.StartsWith(x.Path,StringComparison.OrdinalIgnoreCase))??available.FirstOrDefault();if(previous!=null)preferred=available.FirstOrDefault(x=>string.Equals(x.Path,previous,StringComparison.OrdinalIgnoreCase))??preferred;root.SelectedItem=preferred;}
  static string FormatSize(long bytes){double gb=bytes/1073741824d;return gb.ToString(gb>=100?"0":"0.0",System.Globalization.CultureInfo.InvariantCulture)+" GB";}
  TreeViewItem Node(string text,StorageNode data){var item=new TreeViewItem{Header=text,Tag=data,Foreground=new SolidColorBrush(Color.FromRgb(243,236,228)),Style=TreeItemStyle()};item.Selected+=delegate{item.Background=new SolidColorBrush(Color.FromRgb(54,39,25));item.BorderBrush=new SolidColorBrush(Color.FromRgb(232,150,74));};item.Unselected+=delegate{item.ClearValue(Control.BackgroundProperty);item.ClearValue(Control.BorderBrushProperty);};if(data.Directory){item.Items.Add("Expand to load…");item.Expanded+=async delegate(object sender,RoutedEventArgs e){if(e.OriginalSource!=item||data.Loaded)return;data.Loaded=true;item.Items.Clear();await Load(item,data,0);};}return item;}
  void SelectRightClickedItem(object sender,MouseButtonEventArgs e){DependencyObject current=e.OriginalSource as DependencyObject;while(current!=null){var item=current as TreeViewItem;if(item!=null){item.IsSelected=true;item.Focus();ShowContextPopup(item,item.Tag as StorageNode);e.Handled=true;return;}current=VisualTreeHelper.GetParent(current);}}
