   var template=new ControlTemplate(typeof(TreeViewItem));var root=new FrameworkElementFactory(typeof(StackPanel));root.SetValue(StackPanel.OrientationProperty,Orientation.Vertical);var headerRow=new FrameworkElementFactory(typeof(DockPanel),"HeaderRow");headerRow.SetValue(DockPanel.LastChildFillProperty,true);
   var arrowStyle=new Style(typeof(ToggleButton));arrowStyle.Setters.Add(new Setter(ContentControl.ContentProperty,"›"));arrowStyle.Setters.Add(new Setter(Control.ForegroundProperty,muted));arrowStyle.Setters.Add(new Setter(Control.BackgroundProperty,Brushes.Transparent));arrowStyle.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0)));arrowStyle.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(0)));arrowStyle.Setters.Add(new Setter(FrameworkElement.WidthProperty,16d));arrowStyle.Setters.Add(new Setter(FrameworkElement.HeightProperty,22d));arrowStyle.Setters.Add(new Setter(UIElement.FocusableProperty,false));var arrowTemplate=new ControlTemplate(typeof(ToggleButton));var arrowContent=new FrameworkElementFactory(typeof(ContentPresenter));arrowContent.SetValue(ContentPresenter.HorizontalAlignmentProperty,HorizontalAlignment.Center);arrowContent.SetValue(ContentPresenter.VerticalAlignmentProperty,VerticalAlignment.Center);arrowTemplate.VisualTree=arrowContent;arrowStyle.Setters.Add(new Setter(Control.TemplateProperty,arrowTemplate));var expandedArrow=new Trigger{Property=ToggleButton.IsCheckedProperty,Value=true};expandedArrow.Setters.Add(new Setter(ContentControl.ContentProperty,"⌄"));arrowStyle.Triggers.Add(expandedArrow);
